// OSS ждёт ответ в формате Alibaba Cloud: serverRecvTime - время сервера в миллисекундах (UTC)
let req = {};
try { req = JSON.parse(msg.payload); } catch (e) {}
const now = String(Date.now());
msg.topic = msg.topic.replace(/\/request$/, '/response');
msg.payload = JSON.stringify({ deviceSendTime: String(req.deviceSendTime || ''), serverRecvTime: now, serverSendTime: now });
return msg;

// топик: /sys/<продукт>/<устройство>/thing/event/<property | events:events>/post
const p = msg.topic.split('/');
const pk = p[2], dn = p[3], ident = p[6];
let j;
try { j = JSON.parse(msg.payload); } catch (e) { node.warn('не JSON от ' + dn + ': ' + msg.payload); return null; }
// id - метка времени устройства: секунды и три цифры («1734657290001»)
const now = Math.floor(Date.now() / 1000);
let ts = Math.floor(Number(j.id) / 1000);
if (!ts || ts < 1577836800 || ts > now + 3600) ts = now;   // часы устройства ещё не сверены
const seen = flow.get('seen') || {}; seen[dn] = now; flow.set('seen', seen);
if (ident === 'property') {
    const fields = {};
    for (const [k, v] of Object.entries(j.params || {})) {
        const i = k.indexOf(':');
        const mod = k.slice(0, i), name = k.slice(i + 1);
        if (mod === 'telemetry' && typeof v === 'number' && isFinite(v)) fields[name] = v;
        else if (mod === 'settings') { const info = flow.get('info') || {}; (info[dn] = info[dn] || {})[name] = String(v); flow.set('info', info); }
    }
    if (!Object.keys(fields).length) return null;
    msg.oss = { kind: 'data', pk, dn, ts, fields };
} else {
    msg.oss = { kind: 'event', pk, dn, ts, text: String((j.params || {}).message || '') };
}
return msg;

const o = msg.oss;
const esc = s => String(s).replace(/[ ,=]/g, '\\$&');
let line;
if (o.kind === 'data') {
    const f = Object.entries(o.fields).map(([k, v]) => esc(k) + '=' + v).join(',');
    line = `oss,product=${esc(o.pk)},device=${esc(o.dn)} ${f} ${o.ts}`;
} else {
    const t = o.text.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
    line = `oss_event,product=${esc(o.pk)},device=${esc(o.dn)} message="${t}" ${o.ts}`;
}
const base = env.get('INFLUX_URL') || 'http://influxdb:8086';
msg.url = base + '/api/v2/write?org=' + encodeURIComponent(env.get('INFLUX_ORG')) + '&bucket=' + encodeURIComponent(env.get('INFLUX_BUCKET')) + '&precision=s';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + env.get('INFLUX_TOKEN'), 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = line;
return msg;

if (msg.oss.kind !== 'data') return null;
let cfg = {};
try { cfg = JSON.parse(env.get('THRESHOLDS') || '{}'); } catch (e) { node.warn('THRESHOLDS - не JSON'); return null; }
const st = flow.get('alarm') || {};
const out = [];
for (const [name, v] of Object.entries(msg.oss.fields)) {
    const c = cfg[name];
    if (!c) continue;
    const h = Number(c.hyst || 0), key = msg.oss.dn + '/' + name;
    const hi = c.max !== undefined && v > c.max, lo = c.min !== undefined && v < c.min;
    if (!st[key] && (hi || lo)) {
        st[key] = true;
        out.push({ payload: `⚠️ ${msg.oss.dn}: ${name} = ${v} (${hi ? 'выше ' + c.max : 'ниже ' + c.min})` });
    } else if (st[key]) {
        const okHi = c.max === undefined || v <= c.max - h, okLo = c.min === undefined || v >= c.min + h;
        if (okHi && okLo) { st[key] = false; out.push({ payload: `✅ ${msg.oss.dn}: ${name} = ${v}, снова в норме` }); }
    }
}
flow.set('alarm', st);
return [out];

// события OSS, о которых стоит сообщить сразу; остальные (обновление прошивки и т.п.) только в журнал
if (msg.oss.kind !== 'event') return null;
if (!/unable|fail|out of range|invalid/i.test(msg.oss.text)) return null;
msg.payload = `❗ ${msg.oss.dn}: ${msg.oss.text}`;
return msg;

const lim = (Number(env.get('NODATA_MIN')) || 90) * 60;
const now = Date.now() / 1000;
const seen = flow.get('seen') || {}, lost = flow.get('lost') || {};
const out = [];
for (const [dn, t] of Object.entries(seen)) {
    const late = now - t > lim;
    if (late && !lost[dn]) { lost[dn] = true; out.push({ payload: `📵 ${dn}: нет данных ${Math.round((now - t) / 60)} мин` }); }
    if (!late && lost[dn]) { lost[dn] = false; out.push({ payload: `📶 ${dn}: снова на связи` }); }
}
flow.set('lost', lost);
return [out];

const tok = env.get('TELEGRAM_TOKEN'), chat = env.get('TELEGRAM_CHAT');
node.log(msg.payload);
if (!tok || !chat) { node.status({ fill: 'grey', shape: 'ring', text: 'Telegram не настроен' }); return null; }
const base = env.get('TELEGRAM_API') || 'https://api.telegram.org';
msg.url = base + '/bot' + tok + '/sendMessage';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = JSON.stringify({ chat_id: chat, text: msg.payload });
return msg;
